# Pydantic schemas defining the structures for research plans and tasks.
from typing import Literal

from pydantic import BaseModel, Field

# Individual sub-task generated by the planner agent
class ResearchTask(BaseModel):
    task_id: int = Field(
        description="Unique integer identifier for this task"
    )

    topic: str = Field(
        min_length=3,
        description="Specific research topic"
    )

    description: str = Field(
        min_length=10,
        description="Detailed instructions describing what to investigate"
    )

    priority: Literal["low", "medium", "high"] = Field(
        description="Priority of this research task"
    )

    expected_output: str = Field(
        min_length=5,
        description="Expected findings or deliverable from this task"
    )

# Full structured plan object handed back to the frontend / orchestration engine
class ResearchPlan(BaseModel):
    research_title: str = Field(
        description="Clear title for the research project"
    )

    research_question: str = Field(
        description="Original research question"
    )

    objectives: list[str] = Field(
        min_length=2,
        description="Main objectives of the research"
    )

    tasks: list[ResearchTask] = Field(
        min_length=3,
        max_length=8,
        description="Independent research tasks"
    )

    scope: str = Field(
        description="Research boundaries and areas covered"
    )

    assumptions: list[str] = Field(
        description="Assumptions or uncertainties to consider"
    )



from typing import Literal
from pydantic import BaseModel, Field


class ResearchSource(BaseModel):
    source_id: str
    title: str
    url: str
    snippet: str = ""
    content: str = ""
    content_source: Literal["webpage", "search_snippet"]
    published_date: str | None = None
    retrieved_at: str


class EvidenceClaim(BaseModel):
    claim_id: str
    claim_text: str
    source_id: str
    supporting_passage: str


class WorkerExtraction(BaseModel):
    claims: list[EvidenceClaim] = Field(default_factory=list)
    unanswered_questions: list[str] = Field(default_factory=list)


class ResearchWorkerResult(BaseModel):
    task_id: int
    task_topic: str

    status: Literal["complete", "partial", "failed"]

    sources: list[ResearchSource] = Field(default_factory=list)
    claims: list[EvidenceClaim] = Field(default_factory=list)

    unanswered_questions: list[str] = Field(default_factory=list)

    error: str | None = None
